export interface TagInfo {
  readonly vr: string;
  readonly name: string;
}

const INFO = new Map<number, TagInfo>();
for (const entry of RAW.split("|")) {
  const a = entry.split(",");
  const group = parseInt(a[0] ?? "", 16);
  const elem = parseInt(a[1] ?? "", 16);
  if (Number.isNaN(group) || Number.isNaN(elem)) continue;
  INFO.set((group << 16) | elem, { vr: a[2] ?? "UN", name: a[3] ?? "" });
}

export function tagInfo(group: number, elem: number): TagInfo | undefined {
  return INFO.get((group << 16) | elem);
}

export function tagLabel(group: number, elem: number): string {
  return "(" +
    group.toString(16).toUpperCase().padStart(4, "0") +
    "," +
    elem.toString(16).toUpperCase().padStart(4, "0") +
    ")";
}

export function tagName(group: number, elem: number): string {
  return INFO.get((group << 16) | elem)?.name ?? "";
}

export const KNOWN_TAG_COUNT = INFO.size;
